const $=id=>document.getElementById(id);const timeline={};const raw=INPUT.raw;const model={matches:[INPUT.match],options:INPUT.options};function showPerformance(){}
function showPlayers(index){timeline.detailMatch=model.matches[index];window.OWQS_LAST_ANALYSIS={model,raw,index};queueMicrotask(()=>window.dispatchEvent(new CustomEvent("owqs:analysis-updated",{detail:{model,raw,index}})));
 const m=model.matches[index];
 if(window.QS_REVIEW)window.QS_REVIEW.render(m,raw);
 $('chart').querySelectorAll('.match-hit').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.match)===index)));
 $('performancePanel').hidden=true;
 const time=m?.duration!==null&&m?.duration!==undefined?` · 时长 ${Math.floor(m.duration/60)}:${String(Math.floor(m.duration%60)).padStart(2,'0')}`:'';
 const score=m&&m.teamScore!==null&&m.opponentScore!==null?` · 比分 ${m.teamScore}:${m.opponentScore}`:'';
 $('matchMeta').textContent=m?`本场强度 ${m.mean===null?'—':m.mean.toFixed(1)} · ${m.estimateSource?'估算：'+m.estimateSource:m.mean===null?'缺少可查段位':'实测可查段位均值（'+m.known.length+'/'+m.players.length+'，不代表完整对局）'}${m.estimateRange?' · 参考范围 '+m.estimateRange.min+'—'+m.estimateRange.max:''}${time}${score}`:'';
 const estimate=m?.estimateDetails,aux=estimate?.auxiliary;
 $('estimateDetail').hidden=!estimate;
 const fixed=v=>Number.isFinite(v)?v.toFixed(1):'—';
 $('estimateDetail').innerHTML=estimate?`<div class="estimate-equation"><div><span>${estimate.unanchored?'动态规则参考':'参考段位'}</span><strong>${fixed(estimate.rankBase)}</strong><small>${estimate.rankSamples} 名独立参考 · 近期补充 ${estimate.historySamples} 名</small></div><span class="equation-sign" aria-hidden="true">+</span><div><span>表现调整</span><strong>${aux.delta>=0?'+':''}${fixed(aux.delta)}</strong><small>实际 ${(aux.relativeDelta*100).toFixed(1)}% · 上限 ±35%</small></div><span class="equation-sign" aria-hidden="true">≈</span><div><span>本场估分</span><strong class="estimate-final">${fixed(m.mean)}</strong><small>证据评分 ${m.confidenceEvidence.percent}% · 非实测段位</small></div></div><p>${QS.esc(m.estimateSource)}；原始可查均值 ${fixed(m.observedMean)}（${m.known.length}/${m.players.length}）；本场 ${estimate.recentPlayers} 名玩家已补近期 ${estimate.recentGames} 场参考。${estimate.unanchored?'无段位锚点：分值使用表现映射规则，不能解读为真实段位。':''}${aux.reason?QS.esc(aux.reason)+'。':''}个人缺失段位保持 —，参考范围不是置信区间。</p><p>范围 ${m.estimateRange?m.estimateRange.min+'—'+m.estimateRange.max:'—'} · 本场独立参考 ${estimate.rangeDetails.localSamples} 名（直接 ${estimate.rangeDetails.directSamples} / 近期 ${estimate.rangeDetails.recentSamples}）· 有效样本 ${estimate.rangeDetails.effectiveLocalSamples.toFixed(2)} · 本场段位证据 ${(estimate.rangeDetails.localQuality*100).toFixed(0)}% · 战斗证据 ${((estimate.combatQuality||0)*100).toFixed(0)}%；证据多且一致则收窄，缺少依据或双方悬殊则放宽。</p><p class="combat-balance">${aux.teamScores?.length?`我方表现 ${fixed(aux.teamScores[0].score)} / 对方表现 ${fixed(aux.teamScores[1].score)} · 差距 ${fixed(aux.teamGap)} · 均衡 ${aux.balanceFactor.toFixed(2)} · 一致性 ${aux.consistencyFactor.toFixed(2)} · 悬殊下调 ${(aux.imbalanceRatio*100).toFixed(1)}% · ${QS.esc(aux.context)}`:QS.esc(aux.reason||'缺少双方表现数据')}</p>`:'';

 const value=v=>v===null||v===undefined?'—':v.toLocaleString('zh-CN',{maximumFractionDigits:0});
 $('players').innerHTML=m?m.players.map((p,index)=>{const hero=QS_DATA.heroes[p.hero],icon=window.QS_HERO_ICONS?.[p.hero];return `<tr><td class="${p.name===raw.battletag?'player-self':''}">${QS.esc(p.name)}</td><td><span class="team-label ${p.side==='E'?'enemy':''}">${p.side==='E'?'对方':'我方'}</span></td><td><div class="hero-cell">${icon?`<img src="${QS.esc(icon)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<span>${QS.esc(hero?.name||'未知英雄')}<small>${QS.esc(QS.roles[p.role]||'未知职责')} · ${QS.esc(p.performance?.profileName||'通用定位')}</small></span></div></td><td>${value(p.stats.kill)} / ${value(p.stats.assist)} / ${value(p.stats.death)}</td><td>${value(p.stats.finalHit)}</td><td>${value(p.stats.heroDamage)}</td><td>${value(p.stats.cure)}</td><td>${value(p.stats.resistDamage)}</td><td>${value(p.stats.healingTaken)}</td><td>${value(p.stats.damageTaken)}</td><td class="${p.score===null?'muted':'rank-pill'}">${p.score===null?'—':QS.rank(p.score)}</td><td>${p.score??'—'}</td>${performanceCell(p,index)}</tr>`;}).join(''):'<tr><td colspan="13">查询后显示本局玩家、英雄与游戏数据</td></tr>';
 document.querySelectorAll('.hero-cell img').forEach(img=>img.addEventListener('error',()=>img.hidden=true,{once:true}));
 $('players').querySelectorAll('[data-performance]').forEach(button=>button.onclick=()=>showPerformance(m.players[Number(button.dataset.performance)]));
 $('gameDataStatus').textContent=m?.hasGameData?(m.resourceDataChecked?'英雄为接口返回值；受治疗未拆分来源，承伤与抵挡不同；— 表示未返回。':'正在补齐本场受治疗与承伤数据…'):m?'正在读取本场游戏数据…':'游戏数据来自对局详情';
 $('gameDataStatus').classList.remove('error');$('retryGameData').hidden=true;
 if(m&&(!m.hasGameData||!m.resourceDataChecked)){$('gameDataStatus').textContent='对局记录缺少部分游戏数据；不会自动补查';}
}
function performanceCell(p,index){
 const r=p.performance;
 if(!r.grade)return `<td class="performance-cell"><span class="muted" title="${QS.esc(r.reason)}">待评</span><small>${QS.esc(r.reason)}</small></td>`;
 return `<td class="performance-cell"><button type="button" class="grade grade-${r.grade}" data-performance="${index}" aria-label="查看 ${QS.esc(p.name)} 的 ${r.grade} 级表现评分明细" title="${QS.esc(r.hero)} · ${r.score} 分 · ${QS.esc(r.reference)}；点击查看指标">${r.grade}<span>${r.score.toFixed(1)}</span></button><small>整局估评</small></td>`;
}

if(INPUT.kind==='data'){
 $('matchSelect').innerHTML='<option></option>';
 $('matchSelect').firstChild.textContent='第 '+INPUT.index+' 场 · '+INPUT.mapName;
 showPlayers(0);
}else{
 $('aiReviewPanel').hidden=false;
 $('aiReviewText').classList.remove('muted');
 $('aiReviewText').textContent=INPUT.review;
 $('aiReviewGenerate').hidden=true;$('aiReviewAgain').hidden=false;
 $('aiReviewStatus').textContent='已显示本地保存的锐评';
}
